begin;
insert into profiles(id) values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002');
insert into wallets(user_id,coins) select id,100000 from profiles;
insert into rooms(id) values('10000000-0000-0000-0000-000000000001');
insert into room_members select '10000000-0000-0000-0000-000000000001',id from profiles;
insert into game_catalog(slug,name) values('fruit_party','Real original settlement fixture');
do $$declare settled jsonb;recovered jsonb;balance bigint;begin
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
 settled:=public.play_game('fruit_party',100,'spin',null,'lost-response','10000000-0000-0000-0000-000000000001');
 select coins into balance from wallets where user_id=auth.uid();
 delete from room_members where user_id=auth.uid();
 update game_catalog set active=false;
 recovered:=public.my_game_receipt('10000000-0000-0000-0000-000000000001','fruit_party',100,'lost-response');
 if recovered->>'bet_id'<>settled->>'bet_id' or recovered->>'payout'<>settled->>'payout' or recovered->'result'<>settled->'result' then raise exception 'Settled receipt lost';end if;
 if (select coins from wallets where user_id=auth.uid())<>balance or (select count(*) from game_bets)<>1 then raise exception 'Recovery changed economy';end if;
 begin perform public.my_game_receipt('10000000-0000-0000-0000-000000000001','fruit_party',200,'lost-response');raise exception 'Changed bet accepted';exception when sqlstate '22023' then null;end;
 begin perform public.my_game_receipt('10000000-0000-0000-0000-000000000002','fruit_party',100,'lost-response');raise exception 'Changed room accepted';exception when sqlstate '22023' then null;end;
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
 recovered:=public.my_game_receipt('10000000-0000-0000-0000-000000000001','fruit_party',100,'lost-response');
 if recovered->>'status'<>'missing' then raise exception 'Another account receipt leaked';end if;
 begin perform public.play_game_checked('10000000-0000-0000-0000-000000000001','fruit_party',100,'lost-response','00000000-0000-0000-0000-000000000001');raise exception 'Switched account wager accepted';exception when sqlstate '22023' then if sqlerrm<>'GAME_ACCOUNT_CHANGED' then raise;end if;end;
 if (select coins from wallets where user_id=auth.uid())<>100000 then raise exception 'Switched account was debited';end if;
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
 recovered:=public.play_game_checked('10000000-0000-0000-0000-000000000001','fruit_party',100,'lost-response',auth.uid());
 if recovered->>'bet_id'<>settled->>'bet_id' then raise exception 'Checked settlement lost old receipt';end if;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform public.my_game_receipt('10000000-0000-0000-0000-000000000001','fruit_party',100,'lost-response');raise exception 'Anonymous receipt';exception when sqlstate 'P0001' then if sqlerrm<>'AUTH_REQUIRED' then raise;end if;end;
 if has_function_privilege('anon','public.my_game_receipt(uuid,text,bigint,text)','EXECUTE') then raise exception 'Anonymous execution';end if;
end$$;
rollback;
